{
  "requirement_definitions": [
    {
      "id": "DMSR-3877",
      "title": "Summit to Base Network Reliability",
      "text": "The Summit to Base communications shall be highly reliable, with Mean Time to Repair (MTTR) < summToBaseNetMTTR."
    },
    {
      "id": "DMSR-8923",
      "title": "Summit to Base Network Secondary Link",
      "text": "The Summit to Base communications shall provide at least one secondary link or transport mechanism for minimal operations support in the event of extended outage. This link may include redundant ﬁber optics, microwaves, or transportable media. It shall be capable of transferring one night’s worth of raw data in summToBaseNet2TransMax or less."
    },
    {
      "id": "DMSR-8544",
      "title": "Summit to Base Network Ownership and Operation",
      "text": "The Summit to Base communications link shall be owned and operated by LSST and/or the operations entity to ensure responsiveness of support."
    },
    {
      "id": "DMSR-9590",
      "title": "Base Facility Infrastructure",
      "text": "The Base Facility shall provide suﬃcient computing, storage, and network infrastructure to support buﬀering and forwarding of all raw and crosstalk-corrected image data to the Archive Facility, a complete copy of the Archive Facility data holdings, and compute facilities to support Commissioning activities."
    },
    {
      "id": "DMSR-1839",
      "title": "Base Facility Co-Location with Existing Facility",
      "text": "The Base Facility shall be co-located at an existing facility to leverage existing support and facility resources"
    },
    {
      "id": "DMSR-8952",
      "title": "Commissioning Cluster",
      "text": "The Base Facility shall include a compute cluster to be made available to the Systems Engineering group for use in commissioning. Data Management will not administer or otherwise maintain this cluster following hardware installation. The budget for this cluster shall be at least budgetRelAlertProd of the budget for Alert Production hardware."
    },
    {
      "id": "DMSR-6362",
      "title": "Base Wireless LAN (WiFi)",
      "text": "The Base LAN shall provide minBaseWiFi Wireless LAN (WiFi) and Wireless Access Points in the Base Facility to support connectivity of individual user’s computers to the network backbones."
    },
    {
      "id": "DMSR-1253",
      "title": "Base to Archive Network",
      "text": "The DMS shall provide communications infrastructure between the Base Facility and the Archive Center suﬃcient to carry scientiﬁc data and associated metadata for each image in no more than time baseToArchiveMaxTransferTime."
    },
    {
      "id": "DMSR-5740",
      "title": "Base to Archive Network Availability",
      "text": "The Base to Archive communications shall be highly available, with MTBF > baseToArchNetMTBF."
    }
  ],
